lation":"catalog_work_descriptions","after_row":{"text":"Wanneer Mol zijn vertrouwde hol verlaat, leert hij aan de rivier Rat kennen. Met hem en hun vrienden Das en Pad ontdekt hij een wereld van kleine gewoonten en onverwachte avonturen. Vooral Pads enthousiasme voor nieuwe bezigheden brengt onrust in hun bestaan. De dieren proberen hun onderlinge vriendschap te bewaren terwijl hun verschillende karakters hen telkens voor problemen stellen, in en rond het landschap dat zij thuis noemen.","work_id":978100041,"evidence":[{"url":"https://metadata.isbn.nl/981426/de-wind-in-de-wilgen.html","fact":"Hardback ISBN 9789021680354 verschijningsdatum 05/02/2020 NUR 282 Fictie 7-9 jaar 280 Fictie kinder- en jeugdboeken algemeen imprint Ploegsma uitgever WPG Kindermedia taal Nederlands","sha256":"69d1442cdfe2e56d45b5f60b3d84836945f3c751592363ba41dafdf28e7099b6","checkedAt":"2026-11-01T20:46:38.972Z","sourceAuthors":"Kenneth Grahame , Gérard Joulié"},{"url":"https://www.zwijsen.nl/product/de-wind-in-de-wilgen-9789021680354/","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.zwijsen.nl/product/de-wind-in-de-wilgen-9789021680354/","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Uitgever/auteur; oorspronkelijke gecontroleerde samenvatting","source_type":"official_publisher","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":978300026},"before_row":null},{"key":{"id":978200139},"seq":4,"relation":"editions","after_row":{"id":978200139,"title":"Charlotte''s web","isbn_10":null,"isbn_13":"9789056372125","work_id":978100042,"cover_id":null,"language":"nld","publisher":"Lemniscaat B.V., Uitgeverij","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200139},"seq":5,"relation":"catalog_edition_metadata",