"work_id":978100042,"evidence":[{"url":"https://metadata.isbn.nl/273941/charlotte-s-web.html","fact":"Hardback ISBN 9789056372125 verschijningsdatum 01/01/1999 NUR 282 Fictie 7-9 jaar uitgever Lemniscaat B.V., Uitgeverij taal Nederlands","sha256":"ade2abafcf3ba625ba74ca4e2d60b8d8bb7649593b25aedb6a4afbcea5eb9da6","checkedAt":"2026-11-01T20:44:15.628Z","sourceAuthors":"E.B. White"},{"url":"https://metadata.isbn.nl/273941/charlotte-s-web.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/273941/charlotte-s-web.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":978300027},"before_row":null},{"key":{"id":978200140},"seq":7,"relation":"editions","after_row":{"id":978200140,"title":"Een rimpel in de tijd","isbn_10":null,"isbn_13":"9789024580606","work_id":978100043,"cover_id":null,"language":"nld","publisher":"Luitingh Sijthoff","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200140},"seq":8,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":978100043,"evidence":[{"url":"https://metadata.isbn.nl/1046381/een-rimpel-in-de-tijd.html","fact":"Paperback ISBN 9789024580606 verschijningsdatum 05/03/2018 NUR 283 Fictie 10-12 jaar imprint Luitingh Sijthoff uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sha256":"30f3502b4a3efafb82665b792bcb8536b29d5f1b589243d9b00435be9c519327","checkedAt":"2026-11-01T20:44:17.870Z","sourceAuthors":"Madeleine L''Engle"},{"url":"https://metadata.isbn.nl/ie_fcache/0000261238_Een_rimpel_in_de_tijd_-_filmeditie_0_0.jpg","fact":"Exact edition block and 