n door een Amerikaans landschap dat na een ramp vrijwel levenloos is geworden. As en kou maken iedere stap zwaar, terwijl hun belangrijkste opdracht eenvoudig blijft: overleven zonder elkaar kwijt te raken. Buiten hun onderlinge band is weinig houvast over. Cormac McCarthy volgt hoe liefde tussen ouder en kind stand probeert te houden wanneer de vertrouwde beschaving is verdwenen.","work_id":978100044,"evidence":[{"url":"https://metadata.isbn.nl/108039/de-weg.html","fact":"Paperback ISBN 9789029589826 verschijningsdatum 06/10/2015 NUR 302 Vertaalde literaire roman, novelle imprint De Arbeiderspers uitgever Singel Uitgeverijen taal Nederlands","sha256":"72982d860c7fcba3a90948a61369edef149168a04f273765f8d8b8c919e2e946","checkedAt":"2026-11-01T20:42:05.164Z","sourceAuthors":"Cormac McCarthy"},{"url":"https://metadata.isbn.nl/108039/de-weg.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/108039/de-weg.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":978300029},"before_row":null},{"key":{"id":978200142},"seq":13,"relation":"editions","after_row":{"id":978200142,"title":"De zeven echtgenoten van Evelyn Hugo","isbn_10":null,"isbn_13":"9789026356605","work_id":978100045,"cover_id":null,"language":"nld","publisher":"Ambo|Anthos","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200142},"seq":14,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":978100045,"evidence":[{"url":"https://metadata.isbn.nl/1718637/de-zeven-echtgenoten-van-evelyn-hugo.html","fact":"Paperback ISBN 9789026356605 