heidslijnen doorwerken in opvoeding, geloof, relaties en het zoeken naar een eigen plaats.","work_id":978100047,"evidence":[{"url":"https://metadata.isbn.nl/871840/kleurenblind.html","fact":"Paperback ISBN 9789400507975 verschijningsdatum 21/02/2017 NUR 320 Literaire non-fictie algemeen imprint Lev. uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sha256":"6741accf1a20ecbd33fdf41e7bd6331d5b3d13e04ee9ba1b51cbfef6726b3288","checkedAt":"2026-11-01T20:42:11.953Z","sourceAuthors":"Trevor Noah"},{"url":"https://metadata.isbn.nl/871840/kleurenblind.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/871840/kleurenblind.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":978300031},"before_row":null},{"key":{"id":978200145},"seq":22,"relation":"editions","after_row":{"id":978200145,"title":"Matilda","isbn_10":null,"isbn_13":"9789026169786","work_id":978100048,"cover_id":null,"language":"nld","publisher":"De Fontein Jeugd","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200145},"seq":23,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":978100048,"evidence":[{"url":"https://metadata.isbn.nl/8558/matilda.html","fact":"Hardback ISBN 9789026169786 verschijningsdatum 26/09/2023 NUR 283 Fictie 10-12 jaar 282 Fictie 7-9 jaar imprint De Fontein Jeugd uitgever VBK Media taal Nederlands","sha256":"295e2fe850ac613cbff07b75dfed4c3bc1cddcf06af0e9fb9a3fe38113e2d6c1","checkedAt":"2026-11-01T20:44:45.093Z","sourceAuthors":"Roald Dahl"},{"url":"https://metadata.isbn.nl/ie_fcache/0000494226_Matilda_0_