37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/8558/matilda.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":978300032},"before_row":null},{"key":{"id":978200146},"seq":25,"relation":"editions","after_row":{"id":978200146,"title":"Sjakie en de chocoladefabriek","isbn_10":null,"isbn_13":"9789026129612","work_id":978100049,"cover_id":null,"language":"nld","publisher":"De Fontein Jeugd","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200146},"seq":26,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":978100049,"evidence":[{"url":"https://metadata.isbn.nl/331127/sjakie-en-de-chocoladefabriek.html","fact":"Hardback ISBN 9789026129612 verschijningsdatum 31/08/2017 NUR 283 Fictie 10-12 jaar imprint De Fontein Jeugd uitgever VBK Media taal Nederlands","sha256":"a4a3c11c3f1d83567bdae8eaf5b0a0a9967f3e673d8447bfdcb6082f702425f7","checkedAt":"2026-11-01T20:42:16.448Z","sourceAuthors":"Roald Dahl"},{"url":"https://metadata.isbn.nl/ie_fcache/0000246139_Sjakie_en_de_chocoladefabriek_0_0.jpg","fact":"Exact edition block and human visual review; same observed provider image stem for medium variant.","bytes":53905,"sha256":"90b18042925e73a5e5aa80ed71bfa9e27d8a85fa9fe6974274ce14715fc97bd0","checkedAt":"2026-11-01T21:23:25.302Z"}],"cover_url":"https://metadata.isbn.nl/ie_fcache/0000246139_Sjakie_en_de_chocoladefabriek_0_0.jpg","edition_id":978200146,"bound_title":"Sjakie en de chocoladefabriek","reviewed_at":"2026-11-01T21:37:32+00:00","bound_isbn13":"9789026129612","evidence_url":"https://metadata.isbn.nl/331127/sjakie-en-de-chocoladefabriek.html","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":978300032},"before_row":null},{"key":{"work_id":978100049,"language":"nl"},"seq":27,"relation":"catalog_work_descriptions","after_row":{"text":"Sjakie vindt een gouden toegangskaart in een chocoladereep en mag de geheimzinnige fabriek van Willie Wonka bezoeken. Wat voor hem een onbereikbare droom leek, wordt een tocht langs buitengewone uitvindingen en eetbare wonderen. De fabriek blijkt echter niet alleen een plek om zich te verbazen. Tussen alle verleidingen schuilen ook gevaren, waardoor de rondleiding heel anders verloopt dan een gewoon bezoek aan een snoepfabriek.","work_id":978100049,"evidence":[{"url":"https://metadata.isbn.nl/331127/sjakie-en-de-chocoladefabriek.html","fact":"Hardback ISBN 9789026129612 verschijningsdatum 31/08/2017 NUR 283 Fictie 10-12 jaar imprint De Fontein Jeugd uitgever VBK Media taal Nederlands","sha256":"a4a3c11c3f1d83567bdae8eaf5b0a0a9967f3e673d8447bfdcb6082f702425f7","checkedAt":"2026-11-01T20:42:16.448Z","sourceAuthors":"Roald Dahl"},{"url":"https://metadata.isbn.nl/331127/sjakie-en-de-chocoladefabriek.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/331127/sjakie-en-de-chocoladefabriek.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":978300032},"before_row":null},{"key":{"id":978200147},"seq":28,"relation":"editions","after_row":{"id":978200147,"title":"Rupsje Nooitgenoeg","isbn_10":null,"isbn_13":"9789025755348","work_id":978100050,"cover_id":null,"language":"nld","publisher":"Gottmer","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edi