t de ontwikkeling van een rups.","work_id":978100050,"evidence":[{"url":"https://metadata.isbn.nl/1578990/rupsje-nooitgenoeg.html","fact":"Hardback ISBN 9789025755348 verschijningsdatum 27/09/2013 NUR 273 Prentenboeken ( imprint Gottmer uitgever Gottmer Uitgevers Groep b.v. taal Nederlands","sha256":"ac5c984f281c10501949523ba34a4e27daaedf17577fc2e017ff938dad5669f1","checkedAt":"2026-11-01T20:42:18.628Z","sourceAuthors":"Eric Carle"},{"url":"https://metadata.isbn.nl/81693/rupsje-nooitgenoeg.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/81693/rupsje-nooitgenoeg.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-05-20261101","review_status":"approved","bound_author_id":978300033},"before_row":null}],"batch":"nl007-reviewed-batch-05-20261101-test","project":"hlvujbrmfdlrfxdjwsmb"}',true);set local lock_timeout='3s';set local statement_timeout='30s';
