en plan en krijgt ze hulp van de rat Tommel. Het verhaal volgt hoe onverwachte vriendschappen uitgroeien tot een poging om iemand te beschermen die zichzelf niet kan redden.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/273941/charlotte-s-web.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/273941/charlotte-s-web.html","sha256":"ade2abafcf3ba625ba74ca4e2d60b8d8bb7649593b25aedb6a4afbcea5eb9da6","checkedAt":"2026-11-01T20:44:15.628Z","fact":"Hardback ISBN 9789056372125 verschijningsdatum 01/01/1999 NUR 282 Fictie 7-9 jaar uitgever Lemniscaat B.V., Uitgeverij taal Nederlands","sourceAuthors":"E.B. White"},{"url":"https://metadata.isbn.nl/273941/charlotte-s-web.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789024580606","key":{"id":978200140},"before":null,"after":{"id":978200140,"title":"Een rimpel in de tijd","isbn_10":null,"isbn_13":"9789024580606","work_id":978100043,"cover_id":null,"language":"nld","publisher":"Luitingh Sijthoff","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024580606","key":{"edition_id":"@edition:9789024580606"},"before":null,"after":{"edition_id":"@edition:9789024580606","work_id":978100043,"bound_author_id":978300028,"bound_title":"Een rimpel in de tijd","bound_language":"nld","bound_isbn13":"9789024580606","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000261238_Een_rimpel_in_de_tijd_-_filmeditie_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1046381/een-rimpel-in-de-tijd.html","review_status":"approved","review