is van ambitie, liefde en zorgvuldig bewaarde geheimen tevoorschijn.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1718637/de-zeven-echtgenoten-van-evelyn-hugo.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/1718637/de-zeven-echtgenoten-van-evelyn-hugo.html","sha256":"5228dc5577220b1c7aa2e1c39bcb9dd8c853c692c9930592efccc69f4b59b6ae","checkedAt":"2026-11-01T20:42:07.478Z","fact":"Paperback ISBN 9789026356605 verschijningsdatum 08/02/2022 NUR 302 Vertaalde literaire roman, novelle imprint Ambo|Anthos uitgever Ambo/Anthos B.V. taal Nederlands","sourceAuthors":"Taylor Jenkins Reid"},{"url":"https://metadata.isbn.nl/1718637/de-zeven-echtgenoten-van-evelyn-hugo.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789021027432","key":{"id":978200143},"before":null,"after":{"id":978200143,"title":"IT","isbn_10":null,"isbn_13":"9789021027432","work_id":978100046,"cover_id":null,"language":"nld","publisher":"Luitingh Sijthoff","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789021027432","key":{"edition_id":"@edition:9789021027432"},"before":null,"after":{"edition_id":"@edition:9789021027432","work_id":978100046,"bound_author_id":928300049,"bound_title":"IT","bound_language":"nld","bound_isbn13":"9789021027432","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000530837_IT_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/178659/het.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-05-20261101","evidence"