id":978100047,"language":"nl","bound_author_id":978300031,"text":"Trevor Noah groeit op in Zuid-Afrika als kind van een zwarte moeder en een witte vader, terwijl hun relatie onder de apartheid verboden is. Zijn afkomst maakt gewone gezinsmomenten ingewikkeld en bepaalt hoe anderen hem behandelen. In herinneringen aan zijn jeugd speelt zijn moeder een centrale rol. Met persoonlijke belevenissen laat Noah zien hoe wetgeving en maatschappelijke scheidslijnen doorwerken in opvoeding, geloof, relaties en het zoeken naar een eigen plaats.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/871840/kleurenblind.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/871840/kleurenblind.html","sha256":"6741accf1a20ecbd33fdf41e7bd6331d5b3d13e04ee9ba1b51cbfef6726b3288","checkedAt":"2026-11-01T20:42:11.953Z","fact":"Paperback ISBN 9789400507975 verschijningsdatum 21/02/2017 NUR 320 Literaire non-fictie algemeen imprint Lev. uitgever Bruna Uitgevers B.V., A.W. taal Nederlands","sourceAuthors":"Trevor Noah"},{"url":"https://metadata.isbn.nl/871840/kleurenblind.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789026169786","key":{"id":978200145},"before":null,"after":{"id":978200145,"title":"Matilda","isbn_10":null,"isbn_13":"9789026169786","work_id":978100048,"cover_id":null,"language":"nld","publisher":"De Fontein Jeugd","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789026169786","key":{"edition_id":"@edition:9789026169786"},"before":null,"after":{"edition_id":"@edition:9789026169786","work_id":978100048,"bound_a