erde samenvatting","source_url":"https://metadata.isbn.nl/8558/matilda.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/8558/matilda.html","sha256":"295e2fe850ac613cbff07b75dfed4c3bc1cddcf06af0e9fb9a3fe38113e2d6c1","checkedAt":"2026-11-01T20:44:45.093Z","fact":"Hardback ISBN 9789026169786 verschijningsdatum 26/09/2023 NUR 283 Fictie 10-12 jaar 282 Fictie 7-9 jaar imprint De Fontein Jeugd uitgever VBK Media taal Nederlands","sourceAuthors":"Roald Dahl"},{"url":"https://metadata.isbn.nl/8558/matilda.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789026129612","key":{"id":978200146},"before":null,"after":{"id":978200146,"title":"Sjakie en de chocoladefabriek","isbn_10":null,"isbn_13":"9789026129612","work_id":978100049,"cover_id":null,"language":"nld","publisher":"De Fontein Jeugd","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789026129612","key":{"edition_id":"@edition:9789026129612"},"before":null,"after":{"edition_id":"@edition:9789026129612","work_id":978100049,"bound_author_id":978300032,"bound_title":"Sjakie en de chocoladefabriek","bound_language":"nld","bound_isbn13":"9789026129612","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000246139_Sjakie_en_de_chocoladefabriek_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/331127/sjakie-en-de-chocoladefabriek.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/331127/sjakie-en-de-chocoladefabriek.html","sha256":"a4a3c11c3f1d83567bdae8eaf5b0a0a9967f3e673d8447bfdcb6082f702425f7","checkedAt"